
const menuButton = document.querySelector('.menu-toggle');
const navigation = document.querySelector('.main-nav');

if (menuButton && navigation) {
  menuButton.addEventListener('click', () => {
    const isOpen = navigation.classList.toggle('open');
    menuButton.setAttribute('aria-expanded', String(isOpen));
    menuButton.setAttribute('aria-label', isOpen ? 'Cerrar menú' : 'Abrir menú');
  });

  navigation.querySelectorAll('a').forEach(link => {
    link.addEventListener('click', () => {
      navigation.classList.remove('open');
      menuButton.setAttribute('aria-expanded', 'false');
    });
  });
}

document.getElementById('year').textContent = new Date().getFullYear();


// Animación de carrera con los nueve fotogramas incluidos en este archivo.
(() => {
  const runner = document.getElementById('runningMarietta');
  if (!runner) return;
  const frames = [
    'data:image/png;base64,',
    'data:image/png;base64,',
    'data:image/png;base64,',
    'data:image/png;base64,',
    'data:image/png;base64,',
    'data:image/png;base64,',
    'data:image/png;base64,',
    'data:image/png;base64,',
    'data:image/png;base64,'
  ];
  let frame = 0;
  const startAnimation = () => {
    if (runner.dataset.animationStarted === 'yes') return;
    runner.dataset.animationStarted = 'yes';
    window.setInterval(() => {
      frame = (frame + 1) % frames.length;
      runner.src = frames[frame];
    }, 120);
  };
  if (runner.complete && runner.naturalWidth > 0) {
    startAnimation();
  } else {
    runner.addEventListener('load', startAnimation, { once: true });
  }
})();



// Abre el juego independiente en otra pestaña.
document.addEventListener('DOMContentLoaded', () => {
  document.querySelectorAll('a[href="#abrir-juego-piano-marietta"]').forEach(link => {
    link.addEventListener('click', (event) => {
      event.preventDefault();
      const gameTab = window.open('juego/index.html', '_blank');
      if (!gameTab) alert('Activa las ventanas emergentes para abrir Piano Marietta.');
    });
  });
});
